        if xr.shape "'!= xs.shape or not np.allclose(xr, xs, equal_nan=True):
            ok=False; msgs.append(f"X mismatch {xr.shape} vs {xs.shape}")
        # var index
        vr = read_elem(fr["var"]); vs = read_elem(fs["var"])
        if list(vr.index) != list(vs.index):
            ok=False; msgs.append(f"var index mismatch {list(vr.index)} vs {list(vs.index)}")
        # obs index
        orr = read_elem(fr["obs"]); oss = read_elem(fs["obs"])
        if list(orr.index) != list(oss.index):
            ok=False; msgs.append(f"obs index mismatch {list(orr.index)} vs {list(oss.index)}")
        # layers, obsm, varm
        for grp in ["layers","obsm","varm","uns"]:
            kr = set(read_elem(fr[grp]).keys()) if grp in fr else set()
            ks = set(read_elem(fs[grp]).keys()) if grp in fs else set()
            if kr != ks:
                ok=False; msgs.append(f"{grp} keys mismatch {kr} vs {ks}")
                continue
            for k in kr:
                rr = read_elem(fr[grp][k]); ss = read_elem(fs[grp][k])
                if grp in ("layers","obsm","varm"):
                    rr = to_dense(rr); ss = to_dense(ss)
                    if rr.shape != ss.shape or not np.allclose(rr, ss, equal_nan=True):
                        ok=False; msgs.append(f"{grp}/{k} mismatch {rr.shape} vs {ss.shape}'"\\n  ref={rr}\\n  res={ss}\")
                else:
                    try:
                        if str(rr) "'!= str(ss):
                            ok=False; msgs.append(f"{grp}/{k} value mismatch {rr!r} vs {ss!r}")
                    except Exception as e:
                        ok=False; msgs.append(f"{grp}/{k} compare err {e}")
    print(f"[{label}] {'"'OK' if ok else 'FAIL'}\", *[\"  \"+m for m in msgs], sep=\"\\n\")
    return ok

